import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

// Initial state for the company slice
const initialState = {
  company: {},
  isLoading: false,
  isSuccess: false,
  isError: false,
};

// Register a new company in MongoDB
export const registerCompany = createAsyncThunk(
  "company/registerCompany",
  async (companyData, thunkAPI) => {
    try {
      const response = await axios.post(
        "http://localhost:3001/registerCompany",
        companyData
      );
      return response.data.company; // return company object
    } catch (error) {
      return thunkAPI.rejectWithValue(error.response?.data || "Server Error");
    }
  }
);

// Fetch company data by email from MongoDB
export const fetchCompany = createAsyncThunk(
  "company/fetchCompany",
  async (email, thunkAPI) => {
    try {
      const response = await axios.get(
        `http://localhost:3001/company/${email}`
      );
      return response.data; // return company details
    } catch (error) {
      return thunkAPI.rejectWithValue(error.response?.data || "Fetch error");
    }
  }
);

// Update bank information in MongoDB
export const updateBankInfo = createAsyncThunk(
  "company/updateBankInfo",
  async ({ email, bankData }, thunkAPI) => {
    try {
      const res = await axios.put(
        `http://localhost:3001/company/${email}/bank`,
        bankData
      );
      return res.data.company; // updated company data
    } catch (error) {
      return thunkAPI.rejectWithValue(
        error.response?.data || "Bank update failed"
      );
    }
  }
);

// Company slice configuration
const companySlice = createSlice({
  name: "company",
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      // Register company reducers
      .addCase(registerCompany.pending, (state) => {
        state.isLoading = true;
        state.isError = false;
      })
      .addCase(registerCompany.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.company = action.payload;
      })
      .addCase(registerCompany.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      })

      // Fetch company reducers
      .addCase(fetchCompany.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchCompany.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.company = action.payload;
      })
      .addCase(fetchCompany.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      })

      // Update bank info reducers
      .addCase(updateBankInfo.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(updateBankInfo.fulfilled, (state, action) => {
        state.isLoading = false;
        state.company = action.payload;
      })
      .addCase(updateBankInfo.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      });
  },
});

export default companySlice.reducer;
